import {useEffect,useId,useMemo,useRef,useState} from 'react';
import './palette.css';
// No package catalog was supplied; this application composition assumes only React and native HTML.
export type Command={id:string;label:string;group:string;run:()=>void};
export function CommandPalette({open,onClose,commands,recentIds,onRecentChange}:{open:boolean;onClose:()=>void;commands:Command[];recentIds:string[];onRecentChange:(ids:string[])=>void}){
 const dialog=useRef<HTMLDialogElement>(null),search=useRef<HTMLInputElement>(null),id=useId();
 const [query,setQuery]=useState(''),[active,setActive]=useState(0),[error,setError]=useState('');
 const groups=useMemo(()=>{const result=new Map<string,Command[]>();const matched=commands.filter(c=>c.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));if(!query.trim()){const recent=recentIds.map(i=>commands.find(c=>c.id===i)).filter((c):c is Command=>!!c);if(recent.length)result.set('Recent commands',recent)}for(const command of matched){if(!query.trim()&&recentIds.includes(command.id))continue;const key=command.group||'Commands';result.set(key,[...(result.get(key)??[]),command])}return [...result]},[commands,recentIds,query]);
 const flat=groups.flatMap(([,items])=>items),index=Math.min(active,Math.max(0,flat.length-1));
 useEffect(()=>{if(!open)return;const node=dialog.current!;const previous=document.activeElement as HTMLElement|null;setQuery('');setActive(0);setError('');node.showModal();search.current?.focus();return()=>{node.close();previous?.focus()}},[open]);
 useEffect(()=>{dialog.current?.querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest'})},[index,query]);
 function execute(command:Command){try{command.run();onRecentChange([command.id,...recentIds.filter(i=>i!==command.id)].slice(0,10));onClose()}catch{setError('This command could not run. Try again.')}}
 return <dialog ref={dialog} className="command-palette" aria-labelledby={id+'title'} onCancel={e=>{e.preventDefault();onClose()}}><header><h2 id={id+'title'}>Commands</h2><button onClick={onClose} aria-label="Close command palette">×</button></header><label htmlFor={id+'search'}>Find a command</label><input ref={search} id={id+'search'} role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls={id+'results'} aria-activedescendant={flat[index]?id+'option'+index:undefined} value={query} onChange={e=>{setQuery(e.target.value);setActive(0)}} onKeyDown={e=>{if(e.nativeEvent.isComposing)return;if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();setActive(e.key==='Home'?0:e.key==='End'?Math.max(0,flat.length-1):flat.length?(index+(e.key==='ArrowDown'?1:-1)+flat.length)%flat.length:0)}else if(e.key==='Enter'&&flat[index]){e.preventDefault();execute(flat[index])}}}/><div className="command-results" id={id+'results'} role="listbox" aria-label="Commands">{groups.map(([group,items],g)=><div role="group" aria-labelledby={id+'group'+g} key={group}><h3 id={id+'group'+g}>{group}</h3>{items.map(command=>{const i=flat.indexOf(command);return <div key={command.id} id={id+'option'+i} role="option" aria-selected={i===index} onPointerDown={e=>e.preventDefault()} onClick={()=>execute(command)}>{command.label}</div>})}</div>)}</div>{flat.length===0&&<p role="status">No commands match “{query}”. Try another search.</p>}{error&&<p role="alert">{error}</p>}<footer>↑ ↓ to navigate · Enter to run · Escape to close</footer></dialog>;
}
